//! gRPC server reflection (`grpc.reflection.v1.ServerReflection`, and the older `v1alpha` that
//! some clients still ask for first): tools such as `grpcurl` and `grpcui` list the services and
//! fetch the descriptors of their files, then call methods without the `.proto` files.
//!
//! The descriptors come from a [`DescriptorPool`]: every package generated by
//! `only-protobuf-build` has one (`descriptor_pool()`, built from its `FILE_DESCRIPTOR_SET`).
//!
//! ```no_run
//! # mod helloworld {
//! #     pub fn descriptor_pool() -> &'static only_protobuf::reflect::DescriptorPool { unimplemented!() }
//! #     pub const FILE_DESCRIPTOR_SET: &[u8] = &[];
//! # }
//! use only_grpc::{GrpcServer, reflection};
//! use only_protobuf::reflect::DescriptorPool;
//!
//! // One package:
//! let server = reflection::register(GrpcServer::new(), helloworld::descriptor_pool());
//!
//! // Several: merge their descriptor sets into one pool.
//! let mut pool = DescriptorPool::new();
//! pool.add_file_descriptor_set(helloworld::FILE_DESCRIPTOR_SET).unwrap();
//! let server = reflection::register(GrpcServer::new(), &pool);
//! ```

/// The `grpc.reflection.v1` messages (for reflection clients), generated by
/// `only-protobuf-build`.
#[allow(clippy::all)]
#[rustfmt::skip]
pub mod v1 {
    include!("v1.rs");
}

/// The `grpc.reflection.v1alpha` messages (the same as `v1`, in the old package).
#[allow(clippy::all)]
#[rustfmt::skip]
pub mod v1alpha {
    include!("v1alpha.rs");
}

use std::collections::HashSet;

use only_protobuf::{Message, reflect::DescriptorPool};
use v1::{
    ErrorResponse, ExtensionNumberResponse, FileDescriptorResponse, ListServiceResponse,
    ServerReflectionRequest, ServerReflectionResponse, ServiceResponse,
    server_reflection_request::MessageRequest, server_reflection_response::MessageResponse,
};

use crate::{Code, GrpcServer, Status};

/// The reflection service's own full names.
pub const SERVICE_NAMES: [&str; 2] = [
    "grpc.reflection.v1.ServerReflection",
    "grpc.reflection.v1alpha.ServerReflection",
];

/// Adds the reflection service (both versions) to `server`, answering from `pool` (plus the
/// reflection service's own descriptors). It lists every service of the pool, so give it the
/// pool of the services the server registers.
pub fn register(server: GrpcServer, pool: &DescriptorPool) -> GrpcServer {
    let mut pool = pool.clone();
    // Our own files: cannot fail (generated, and their imports are none).
    let _ = pool.add_file_descriptor_set(v1::FILE_DESCRIPTOR_SET);
    let _ = pool.add_file_descriptor_set(v1alpha::FILE_DESCRIPTOR_SET);
    let mut server = server;
    for name in SERVICE_NAMES {
        let pool = pool.clone();
        server = server.bidi(&format!("/{name}/ServerReflectionInfo"), move |_md, sink| {
            let pool = pool.clone();
            let mut sent: HashSet<String> = HashSet::new();
            Box::new(move |m| match m {
                Some(b) => match ServerReflectionRequest::decode(&b) {
                    Ok(req) => {
                        let resp = answer(&pool, req, &mut sent);
                        sink.send(&resp.encode_to_vec());
                    }
                    Err(e) => sink.finish(Status::new(Code::InvalidArgument, e.to_string())),
                },
                None => sink.finish(Status::ok()),
            })
        });
    }
    server
}

/// The answer to one request. `sent` holds the files already sent on this stream (a file and
/// its imports are sent once, as grpc-go does).
fn answer(
    pool: &DescriptorPool,
    req: ServerReflectionRequest,
    sent: &mut HashSet<String>,
) -> ServerReflectionResponse {
    let not_found = |m: String| {
        MessageResponse::ErrorResponse(ErrorResponse {
            error_code: Code::NotFound as i32,
            error_message: m,
        })
    };
    let files = |name: &str, sent: &mut HashSet<String>| {
        let mut out = Vec::new();
        let mut stack = vec![name.to_owned()];
        let mut first = true;
        while let Some(n) = stack.pop() {
            let Some(f) = pool.get_file_by_name(&n) else {
                continue;
            };
            // The requested file always; its imports once per stream.
            if !first && sent.contains(&n) {
                continue;
            }
            first = false;
            sent.insert(n);
            out.push(f.proto().encode_to_vec());
            stack.extend(f.proto().dependency.iter().cloned());
        }
        MessageResponse::FileDescriptorResponse(FileDescriptorResponse {
            file_descriptor_proto: out,
        })
    };
    let response = match &req.message_request {
        Some(MessageRequest::FileByFilename(n)) => match pool.get_file_by_name(n) {
            Some(_) => files(n, sent),
            None => not_found(format!("file not found: {n}")),
        },
        Some(MessageRequest::FileContainingSymbol(s)) => match pool.file_containing_symbol(s) {
            Some(f) => files(f.name(), sent),
            None => not_found(format!("symbol not found: {s}")),
        },
        Some(MessageRequest::FileContainingExtension(x)) => {
            let found = pool
                .get_message_by_name(&x.containing_type)
                .and_then(|m| pool.get_extension(&m, x.extension_number.max(0) as u32));
            match found {
                Some(e) => {
                    let f = pool.file_containing_symbol(e.full_name());
                    match f {
                        Some(f) => files(f.name(), sent),
                        None => not_found(format!("extension not found: {}", e.full_name())),
                    }
                }
                None => not_found(format!(
                    "extension {} of {} not found",
                    x.extension_number, x.containing_type
                )),
            }
        }
        Some(MessageRequest::AllExtensionNumbersOfType(t)) => match pool.get_message_by_name(t) {
            Some(m) => {
                let mut nums: Vec<i32> = m.extensions().iter().map(|e| e.number() as i32).collect();
                nums.sort_unstable();
                MessageResponse::AllExtensionNumbersResponse(ExtensionNumberResponse {
                    base_type_name: m.full_name().to_owned(),
                    extension_number: nums,
                })
            }
            None => not_found(format!("type not found: {t}")),
        },
        Some(MessageRequest::ListServices(_)) => {
            let mut names: Vec<String> = pool.services().map(|s| s.full_name().to_owned()).collect();
            names.sort();
            names.dedup();
            MessageResponse::ListServicesResponse(ListServiceResponse {
                service: names
                    .into_iter()
                    .map(|name| ServiceResponse { name })
                    .collect(),
            })
        }
        None => MessageResponse::ErrorResponse(ErrorResponse {
            error_code: Code::InvalidArgument as i32,
            error_message: "empty request".into(),
        }),
    };
    ServerReflectionResponse {
        valid_host: req.host.clone(),
        original_request: Some(req),
        message_response: Some(response),
    }
}

#[cfg(test)]
mod tests {
    use only_protobuf::well_known;

    use super::*;

    fn ask(pool: &DescriptorPool, r: MessageRequest, sent: &mut HashSet<String>) -> MessageResponse {
        answer(
            pool,
            ServerReflectionRequest {
                host: "h".into(),
                message_request: Some(r),
            },
            sent,
        )
        .message_response
        .unwrap()
    }

    #[test]
    fn answers() {
        let mut pool = well_known::descriptor_pool().clone();
        pool.add_file_descriptor_set(v1::FILE_DESCRIPTOR_SET).unwrap();
        let mut sent = HashSet::new();
        let MessageResponse::ListServicesResponse(l) =
            ask(&pool, MessageRequest::ListServices(String::new()), &mut sent)
        else {
            panic!()
        };
        assert_eq!(l.service[0].name, "grpc.reflection.v1.ServerReflection");
        let MessageResponse::FileDescriptorResponse(f) = ask(
            &pool,
            MessageRequest::FileContainingSymbol(
                "grpc.reflection.v1.ServerReflection.ServerReflectionInfo".into(),
            ),
            &mut sent,
        ) else {
            panic!()
        };
        let fd = well_known::FileDescriptorProto::decode(&f.file_descriptor_proto[0]).unwrap();
        assert_eq!(fd.name.as_deref(), Some("grpc/reflection/v1/reflection.proto"));
        let MessageResponse::ErrorResponse(e) = ask(
            &pool,
            MessageRequest::FileContainingSymbol("no.Such".into()),
            &mut sent,
        ) else {
            panic!()
        };
        assert_eq!(e.error_code, Code::NotFound as i32);
        let MessageResponse::AllExtensionNumbersResponse(x) = ask(
            &pool,
            MessageRequest::AllExtensionNumbersOfType("google.protobuf.FieldOptions".into()),
            &mut sent,
        ) else {
            panic!()
        };
        assert!(x.extension_number.is_empty());
    }
}
